//! Potsdam in 1900, from historical-walk's generated city: the same
//! `city.json` its app loads, drawn by this engine. The ground is the
//! city's terrain grid with the river carved in and the land use painted
//! on; buildings, walls, bridges, trees and lamps are built from the data
//! at startup.

mod build;
mod city;
mod ground;

use std::sync::Arc;

use tranquility::prelude::*;

use crate::{build::CityData, city::City, ground::CityGround};

/// Generated by historical-walk (`npm run city potsdam`); see the README.
const CITY: &str = include_str!("../data/potsdam.json");

fn main() {
    let city: City = serde_json::from_str(CITY).expect("city.json parses");
    let ground = Arc::new(CityGround::new(&city));
    let world = WorldDef {
        name: format!("{} {}", city.name, city.year),
        ground: ground.clone(),
        // A metre between vertices out to 250–500 m, where streets and
        // squares are drawn; five levels reach 4 km.
        terrain: TerrainSettings {
            chunk_size: 128.0,
            resolution: 128,
            levels: 5,
            ring: 1,
            roughness: 0.95,
            reflectance: 0.3,
            // The town is flat: buildings cast, the ground only receives.
            casts_shadows: false,
            ..default()
        },
        sky: SkySettings {
            sun: SunPath::Daily {
                latitude: 52.4,
                declination: 12.0,
            },
            start_hour: 10.0,
            // Light bounced off the walls into the streets, which the sky's
            // own light leaves out.
            ambient: 2500.0,
            ..default()
        },
        water: Some(WaterSettings {
            level: city.water,
            color: Color::srgb(0.03, 0.05, 0.04),
            roughness: 0.04,
        }),
        walker: WalkerSettings {
            walk_on_water: false,
            ..default()
        },
        spawn: Spawn {
            x: city.spawn.x as f64,
            z: city.spawn.z as f64,
            yaw: city.spawn.yaw,
            pitch: 0.02,
        },
    };

    let mut app = tranquility::app(world);
    app.insert_resource(CityData(Arc::new(city), ground))
        .add_systems(Startup, build::spawn)
        .add_systems(Update, landmark);
    app.run();
}

/// Names the landmark in view: the nearest label within reach that lies
/// ahead.
fn landmark(data: Res<CityData>, mut hud: ResMut<Hud>, player: Single<&Transform, With<Player>>) {
    let p = player.translation.xz();
    let ahead = player.forward().xz().normalize_or_zero();
    let best = data
        .0
        .labels
        .iter()
        .filter_map(|l| {
            let to = Vec2::new(l.x, l.z) - p;
            let d = to.length();
            let reach = l.r.unwrap_or(10.0) + 60.0;
            (d < reach && (d < 15.0 || to.dot(ahead) > 0.5 * d)).then_some((d, l))
        })
        .min_by(|a, b| a.0.total_cmp(&b.0));
    let text = match best {
        Some((_, l)) => match &l.about {
            Some(about) => format!("{}: {}", l.text, about),
            None => l.text.clone(),
        },
        // The data's licences ask for attribution; show it whenever nothing
        // else is.
        None => data.0.credits.join(" · "),
    };
    if hud.info != text {
        hud.info = text;
    }
}
